BEGIN TRANSACTION;

UPDATE enrollments SET completed = 1, progress = 100
WHERE developer_id = 7 AND course_id = 12;

UPDATE developers SET hours_studied = hours_studied + 10
WHERE id = 7;

-- Inspect: did both do what you expected?
-- Yes → COMMIT TRANSACTION;   (changes become permanent & visible)
-- No  → ROLLBACK TRANSACTION; (both changes vanish, as if never run)

